    if bh is not None and bh <= -float(cs["掉分即时线"]):
        wt.append({"编号": f"{k}-diaofen", "级别": "P1", "标题": f"{duan(ming)}体验分掉 {abs(bh):g} 分", "对象": ming,
                   "说明": (f"后台诊断：{ty['短板']}" if ty.get("短板") else "")[:300], "建议": "看掉在哪一项，商品看品退差评、服务看客服响应", "派给": "掌柜"})
    if fen.get("等我们回"):
