    jg[f"{k}_paihang"] = xiang(f"{duan(ming)}各款排行前5", bang(w.get("商品榜"), "商品", "成交金额"), chu("商品榜") + "·成交金额")
    jg[f"{k}_darenbang"] = xiang(f"{duan(ming)}带货达人前5", bang(w.get("达人榜"), "达人", "近30日销售额"), chu("达人榜"))
